SKquests_Alliance = {
    [1] = {
        step = 1,
        title = [[1-5 Northshire Valley — Circuit 1]],
        objectives = [[01) Pick up these 7 quests around Deputy Willem (48.2, 42.9): "A Threat Within", "Kobold Camp Cleanu]],
        text = [[
01) Pick up these 7 quests around Deputy Willem (48.2, 42.9): "A Threat Within", "Kobold Camp Cleanup", "Wolves Across the Border", "Eagan Peltskinner", "Investigate Echo Ridge", "Skirmish at Echo Ridge", "Report to Goldshire".
02) Do "A Threat Within" (48.9, 41.6): Speak with Marshal McBride.
03) Do "Kobold Camp Cleanup" (48.9, 41.6): Kill 8 Kobold Vermin, then return to Marshal McBride.
04) Do "Investigate Echo Ridge" (48.9, 41.6): Kill 8 Kobold Workers, then report back to Marshal McBride.
05) Do "Skirmish at Echo Ridge" (48.9, 41.6): Kill 8 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.
06) Do "Wolves Across the Border" (48.9, 40.2): Bring 8 Diseased Wolf Pelts to Eagan Peltskinner outside Northshire Abbey.
07) Do "Eagan Peltskinner" (48.9, 40.2): Speak with Eagan Peltskinner.
08) Do "Report to Goldshire" (42.1, 65.9): Take Marshal McBride's Documents to Marshal Dughan in Goldshire.
09) Turn in "A Threat Within" and "Kobold Camp Cleanup" and "Investigate Echo Ridge" and "Skirmish at Echo Ridge" to Marshal McBride (48.9, 41.6).
10) Turn in "Wolves Across the Border" and "Eagan Peltskinner" to Eagan Peltskinner (48.9, 40.2).
11) Turn in "Report to Goldshire" to Marshal Dughan (42.1, 65.9).
        ]],
        image = "Alliance_Northshire_c01.tga",
    },
