05) Do "Treant Muisek" (74.4, 43.4): Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.
06) Do "Mountain Giant Muisek" (74.4, 43.4): Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen...
07) Do "Weapons of Spirit" (74.4, 43.4): Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.
08) Do "Improved Quality" (74.4, 42.9): Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas.
09) Turn in "Faerie Dragon Muisek" and "Testing the Vessel" and "Hippogryph Muisek" and "Treant Muisek" and "Mountain Giant Muisek" and "Weapons of Spirit" to Witch Doctor Uzer'i (74.4, 43.4).
