07) Do "Purified!" (51.3, 81.5): Speak to Eridan again in a moment.
08) Do "Further Corruption" (51.3, 81.5): Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8...
09) Turn in "Salve via Hunting" and "Salve via Mining" and "Salve via Gathering" and "Salve via Skinning" and "Salve via Disenchanting" to Maybess Riverbreeze (46.7, 83.1).
