07) Do "The Corruption of the Jadefire" (51.3, 81.5): Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to...
08) Do "Felbound Ancients" (51.3, 81.5): Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the...
09) Turn in "Salve via Gathering" and "Salve via Skinning" and "Salve via Disenchanting" to Arathandris Silversky (54.1, 86.8).
10) Turn in "Dousing the Flames of Protection" and "A Final Blow" to Greta Mosshoof (51.2, 82.1).
11) Turn in "The Corruption of the Jadefire" and "Felbound Ancients" to Eridan Bluewind (51.3, 81.5).
